import type { NextRequest } from "next/server";
import { useCases } from "@/core/di/container";
import { readSession } from "@/features/auth/infrastructure/session-cookies";
import { handleError } from "@/app/api/_shared/handle-error";
import { DomainError } from "@/core/errors/errors";

/** GET /api/evaluation-results/:resultId/pdf — streams the PDF report generated by the backend. */
export async function GET(
  _request: NextRequest,
  ctx: RouteContext<"/api/evaluation-results/[resultId]/pdf">,
) {
  try {
    const session = await readSession();
    if (!session) {
      throw new DomainError("No autorizado. Inicia sesión de nuevo.", 401);
    }

    const { resultId } = await ctx.params;
    const file = await useCases.downloadEvaluationResultPdf.execute(Number(resultId), session.jwt);

    return new Response(file.body, {
      status: 200,
      headers: {
        "Content-Type": file.contentType,
        "Content-Disposition":
          file.contentDisposition ?? `attachment; filename="informe-evaluacion-${resultId}.pdf"`,
        "Cache-Control": "no-store",
      },
    });
  } catch (error) {
    return handleError(error);
  }
}
